1	import ReachyKit
2	import SwiftUI
3	
4	/// Entry point for the shared UI: connection flow → robot control, with one live
5	/// viewport placed according to how much room there is.
6	///
7	/// The tab bar lives here rather than in the app target because the Live tab and
8	/// the Robot tab share a `RobotSession` and a `ViewportModel`, and because
9	/// whether Live exists at all depends on the size class — which an `App` cannot
10	/// read. Diagnostics is injected so the app target keeps owning its own screen
11	/// without a second, nested tab bar.
12	public struct ReachyRootView<Diagnostics: View>: View {
13	    private enum TabID: Hashable {
14	        case robot
15	        case live
16	        case diagnostics
17	    }
18	
19	    @State private var session: RobotSession
20	    @State private var viewport: ViewportModel
21	    @State private var tab: TabID = .robot
22	    @State private var showsSettings = false
23	    @Environment(\.scenePhase) private var scenePhase
24	    @Environment(\.reachyPreviewMode) private var previewMode
25	
26	    #if os(macOS)
27	        /// `horizontalSizeClass` does not exist on macOS, where a window is always
28	        /// wide enough for the two-column layout.
29	        private var isCompact: Bool {
30	            false
31	        }
32	    #else
33	        @Environment(\.horizontalSizeClass) private var horizontalSizeClass
34	        private var isCompact: Bool {
35	            horizontalSizeClass == .compact
36	        }
37	    #endif
38	
39	    private let diagnostics: Diagnostics
40	
41	    @MainActor
42	    public init(@ViewBuilder diagnostics: () -> Diagnostics) {
43	        self.init(session: RobotSession(), diagnostics: diagnostics)
44	    }
45	
46	    /// Internal so previews can park the root in a phase a real connection would have to reach.
47	    @MainActor
48	    init(
49	        session: RobotSession,
50	        viewport: ViewportModel = ViewportModel(),
51	        @ViewBuilder diagnostics: () -> Diagnostics
52	    ) {
53	        _session = State(initialValue: session)
54	        _viewport = State(initialValue: viewport)
55	        self.diagnostics = diagnostics()
56	    }
57	
58	    public var body: some View {
59	        TabView(selection: $tab) {
60	            Tab("Robot", systemImage: "figure.wave", value: TabID.robot) {
61	                robotTab
62	            }
63	            if offersLiveTab {
64	                Tab("Live", systemImage: "cube.transparent", value: TabID.live) {
65	                    liveTab
66	                }
67	            }
68	            Tab("Diagnostics", systemImage: "stethoscope", value: TabID.diagnostics) {
69	                diagnostics
70	            }
71	        }
72	        .task(id: viewportAddress) {
73	            guard !previewMode else { return }
74	            if let viewportAddress {
75	                viewport.attach(to: viewportAddress)
76	            } else {
77	                viewport.detach()
78	            }
79	        }
80	        .onChange(of: viewportIsOnScreen, initial: true) { _, onScreen in
81	            guard !previewMode else { return }
82	            viewport.setActive(onScreen)
83	        }
84	        .onChange(of: offersLiveTab) { _, offered in
85	            // The tab it points at is about to stop existing; SwiftUI would pick
86	            // a replacement of its own, which lands on Diagnostics.
87	            if !offered, tab == .live {
88	                tab = .robot
89	            }
90	        }
91	    }
92	
93	    // MARK: - Tabs
94	
95	    @ViewBuilder
96	    private var robotTab: some View {
97	        switch session.phase {
98	        case .idle, .connecting:
99	            ConnectionScreen(session: session)
100	        case .connected, .unreachable:
101	            if isCompact {
102	                NavigationStack { RobotScreen(session: session) }
103	            } else {
104	                HStack(spacing: 0) {
105	                    wideViewport
106	                    Divider()
107	                    NavigationStack {
108	                        RobotScreen(session: session)
109	                            .columnTitleStyle()
110	                    }
111	                    .frame(minWidth: 320, idealWidth: 380, maxWidth: 420)
112	                }
113	            }
114	        }
115	    }
116	
117	    @ViewBuilder
118	    private var wideViewport: some View {
119	        if viewportAddress == nil {
120	            ContentUnavailableView(
121	                "No live view",
122	                systemImage: "cube.transparent",
123	                description: Text("Start the robot backend to see the model and the camera.")
124	            )
125	            .frame(maxWidth: .infinity, maxHeight: .infinity)
126	        } else if session.isAwake {
127	            ViewportView(model: viewport, offersCamera: session.hasCamera)
128	        } else {
129	            asleepViewport
130	        }
131	    }
132	
133	    private var liveTab: some View {
134	        NavigationStack {
135	            // No `ignoresSafeArea` here: the camera hangs its joystick off a
136	            // bottom safe-area inset, which would then be laid out under the tab
137	            // bar and clipped.
138	            liveContent
139	                .navigationTitle("Live")
140	                .darkTitleBar()
141	                .toolbar {
142	                    ToolbarItem {
143	                        Button {
144	                            showsSettings = true
145	                        } label: {
146	                            Label("Settings", systemImage: "gearshape")
147	                        }
148	                    }
149	                }
150	                .sheet(isPresented: $showsSettings) {
151	                    NavigationStack {
152	                        SettingsScreen(session: session)
153	                            .toolbar {
154	                                ToolbarItem(placement: .cancellationAction) {
155	                                    Button("Done") { showsSettings = false }
156	                                }
157	                            }
158	                    }
159	                    .presentationDetents([.medium, .large])
160	                }
161	        }
162	    }
163	
164	    /// Both streams would keep working while the robot sleeps — the camera hangs off
165	    /// `get_daemon` and the state stream off a running backend — but working is not the
166	    /// same as worth having. A motionless pose and a still frame cost the robot's radio
167	    /// and this phone's battery to show nothing, and a switcher between two inert views
168	    /// is a control that leads nowhere. So the tab keeps its place and offers the one
169	    /// thing that changes the situation.
170	    @ViewBuilder
171	    private var liveContent: some View {
172	        if session.isAwake {
173	            ViewportView(model: viewport, offersCamera: session.hasCamera)
174	        } else {
175	            asleepViewport
176	        }
177	    }
178	
179	    private var asleepViewport: some View {
180	        AsleepBanner(session: session)
181	            .padding()
182	            .frame(maxWidth: 420)
183	            .frame(maxWidth: .infinity, maxHeight: .infinity)
184	    }
185	
186	    // MARK: - Placement
187	
188	    /// Only on iPhone: where there is room, the viewport sits beside the controls
189	    /// instead of behind a tab.
190	    private var offersLiveTab: Bool {
191	        isCompact && viewportAddress != nil
192	    }
193	
194	    /// Both the geometry and the state routes sit behind the backend, so an
195	    /// address alone is not enough to show anything.
196	    private var viewportAddress: RobotAddress? {
197	        session.isBackendRunning ? session.address : nil
198	    }
199	
200	    /// The single lever for battery: nothing streams unless the viewport is the
201	    /// thing the user is actually looking at — and a sleeping robot is never that,
202	    /// however visible the tab is.
203	    private var viewportIsOnScreen: Bool {
204	        guard scenePhase == .active, viewportAddress != nil, session.isAwake else { return false }
205	        return isCompact ? tab == .live : tab == .robot
206	    }
207	}
208	
209	private extension View {
210	    /// A large title inside a narrow side column is laid out against the window
211	    /// rather than the column, so it starts flush against the divider with no
212	    /// leading inset. Inline titles sit correctly.
213	    func columnTitleStyle() -> some View {
214	        #if os(iOS)
215	            navigationBarTitleDisplayMode(.inline)
216	        #else
217	            self
218	        #endif
219	    }
220	
221	    /// The bar cannot take a background over the viewport — both
