import Network

// Mirrors RobotBrowser.start() exactly: same endpoint, same parameters, same queue.
let type = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "_reachy-mini._tcp"
let browser = NWBrowser(for: .bonjour(type: type, domain: nil), using: .tcp)

browser.stateUpdateHandler = { state in
    print("state: \(state)")
}
browser.browseResultsChangedHandler = { results, changes in
    print("results: \(results.count) changes: \(changes.count)")
    for result in results {
        print("  endpoint: \(result.endpoint)")
        if case let .service(name, serviceType, domain, interface) = result.endpoint {
            print("    .service name=\(name) type=\(serviceType) domain=\(domain) iface=\(String(describing: interface))")
        } else {
            print("    NOT a .service case")
        }
    }
}
browser.start(queue: .main)

DispatchQueue.main.asyncAfter(deadline: .now() + 8) {
    print("--- timeout, giving up ---")
    exit(0)
}
RunLoop.main.run()

