                        name: name,
                        type: type,
                        endpoint: .service(name: name, type: type, domain: "local.", interface: nil)
                    )
                },
            ]
            if permissionDenied {
                browser.browserStates = [type: "waiting(-65570: PolicyDenied)"]
            }
            return browser
        }
    }
